ee:message.ee:set-payload:
%dw 2.0
output application/json
var orden = vars.responseById.resultados[0]
var item = (orden.items filter ($.idItem == payload.idItem))[0]
var cuentaFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == item.idCuentaFacturacion))[0]
---
{
 accounts: {
	 idBussines: orden.cliente.idCuenta default "", 
     billingAccounts: [{
             Id: cuentaFacturacion.idCuentaFacturacion default "",
             ciclodeFacturacion: cuentaFacturacion.cicloFacturacion default "" ,
             numberBillingAccount: cuentaFacturacion.cuentaFacturacion default "" ,
			 billingCreationDate: cuentaFacturacion.fechaCreacion default ""
         }
     ]

 },
 items: [{
         idItem: item.idItem default "",
         statusProvisioning: "FacturacionManual",
         billingStartDate: item.fechaInicioFacturacion default "",
		 billingCreationDate: item.fechaInicioFacturacion default ""
     }
 ]
}

%dw 2.0
output application/json
var orden = vars.responseById.resultados[0]
var item = (orden.items filter ($.idOrigen == payload.Revchain_Respuesta_Proceso.WsRequestBody.orden_comercial))[0]
var cuentaFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == item.idCuentaFacturacion))[0]
---
{
 accounts: {
	 idBussines: orden.cliente.idCuenta default "", 
     billingAccounts: [{
             Id: cuentaFacturacion.idCuentaFacturacion default "",
             ciclodeFacturacion: cuentaFacturacion.cicloFacturacion default "" ,
             numberBillingAccount: cuentaFacturacion.cuentaFacturacion default "" ,
			 billingCreationDate: cuentaFacturacion.fechaCreacion default ""
         }
     ]

 },
 items: [{
         idItem: item.idItem default "",
         statusProvisioning: "FacturacionManual",
         billingStartDate: (item.fechaInicioFacturacion splitBy "T")[0] default "",
		 billingCreationDate: (item.fechaInicioFacturacion splitBy "T")[0] default "",
     }
 ]
}
